import os
import sqlite3
from datetime import datetime, timezone

from flask import Flask, render_template_string, request, redirect, url_for, flash, abort
from itsdangerous import URLSafeTimedSerializer

# --- Configuration ---
app = Flask(__name__)

# Get secret from environment variable, fallback to a default for development
app_secret = os.environ.get("APP_SECRET")
if app_secret:
    app.config["SECRET_KEY"] = app_secret
else:
    app.config["SECRET_KEY"] = "dev-secret-key-change-me"

# --- Database Setup ---
DB_NAME = "db.sqlite3"

def get_db():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    with app.app_context():
        db = get_db()
        db.execute("""
            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                content TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
        """)
        db.commit()

init_db()

# --- Helpers ---
def format_message(msg):
    """Format a database row into a dictionary for the template."""
    return {
        "id": msg["id"],
        "username": msg["username"],
        "content": msg["content"],
        "created_at": msg["created_at"]
    }

# --- Template ---
HTML_TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MyForum</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
        .post { border: 1px solid #ddd; padding: 1rem; margin-bottom: 1rem; border-radius: 8px; background: #f9f9f9; }
        .post-meta { font-size: 0.85rem; color: #666; margin-bottom: 0.5rem; }
        .post-content { white-space: pre-wrap; }
        .form-group { margin-bottom: 1rem; }
        input, textarea, select, button { padding: 0.5rem; font-size: 1rem; width: 100%; max-width: 100%; box-sizing: border-box; }
        button { background: #007bff; color: white; border: none; cursor: pointer; }
        button:hover { background: #0056b3; }
        .error { color: red; margin-bottom: 1rem; }
        .nav { margin-bottom: 2rem; padding-bottom: 2rem; border-bottom: 1px solid #eee; }
        .nav a { margin-right: 1rem; color: #007bff; text-decoration: none; }
        .nav a.active { font-weight: bold; }
    </style>
</head>
<body>
    <div class="nav">
        <a href="/">Messages</a>
        <a href="/post">Post Message</a>
    </div>

    <h1>MyForum</h1>

    {% with messages = messages %}
        {% if messages %}
            {% for msg in messages %}
                <div class="post">
                    <div class="post-meta">
                        <strong>{{ msg.username }}</strong> on {{ msg.created_at }}
                    </div>
                    <div class="post-content">{{ msg.content }}</div>
                </div>
            {% endfor %}
        {% else %}
            <p>No messages yet. Be the first to post!</p>
        {% endif %}
    {% endwith %}

    {% with errors = get_flashed_messages() %}
        {% if errors %}
            <div class="error">
                {% for error in errors %}
                    <p>{{ error }}</p>
                {% endfor %}
            </div>
        {% endif %}
    {% endwith %}

    {% if session.get('username') %}
        <div class="form-group">
            <form action="/post" method="POST">
                <input type="hidden" name="username" value="{{ session.username }}">
                <textarea name="content" placeholder="What's on your mind?"></textarea>
                <button type="submit">Post</button>
            </form>
        </div>
    {% else %}
        <div class="form-group">
            <form action="/login" method="POST">
                <input type="text" name="username" placeholder="Username">
                <button type="submit">Login</button>
            </form>
        </div>
    {% endif %}
</body>
</html>
"""

# --- Routes ---

@app.route("/")
def index():
    # Parse query parameters
    limit = int(request.args.get("limit", 10))
    offset = int(request.args.get("offset", 0))
    sort = request.args.get("sort", "desc").upper()

    # Validate sort
    if sort not in ["ASC", "DESC"]:
        sort = "DESC"

    db = get_db()

    # Build query
    order_dir = "ASC" if sort == "ASC" else "DESC"

    # Get total count
    count_row = db.execute("SELECT COUNT(*) as cnt FROM messages").fetchone()
    total = count_row["cnt"]

    # Get messages with pagination and sorting
    messages = db.execute(
        f"SELECT id, username, content, created_at FROM messages ORDER BY created_at {order_dir} LIMIT ? OFFSET ?",
        (limit, offset)
    ).fetchall()

    # Format messages
    formatted_messages = [format_message(m) for m in messages]

    return render_template_string(HTML_TEMPLATE, messages=formatted_messages, total=total)

@app.route("/post", methods=["GET", "POST"])
def post():
    if request.method == "POST":
        username = request.form.get("username", "anonymous")
        content = request.form.get("content", "").strip()

        if not content:
            flash("Content cannot be empty!")
            return redirect(url_for("post"))

        # Sanitize input basicy
        # We store as is, client side should ideally sanitize, but server side is key.
        # For this simple app, we just store.

        db = get_db()
        created_at = datetime.now(timezone.utc).isoformat()

        db.execute(
            "INSERT INTO messages (username, content, created_at) VALUES (?, ?, ?)",
            (username, content, created_at)
        )
        db.commit()

        return redirect(url_for("index"))

    # GET request
    # Determine username from session if logged in, else "anonymous"
    username = session.get("username", "anonymous")
    return render_template_string(HTML_TEMPLATE, messages=[], username=username)

@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username", "").strip()
    if not username:
        flash("Username is required!")
        return redirect(url_for("index"))

    # Store username in session
    session["username"] = username
    return redirect(url_for("index"))

@app.route("/logout")
def logout():
    session.pop("username", None)
    return redirect(url_for("index"))

# --- Main ---
if __name__ == "__main__":
    # Run on 0.0.0.0:5000
    app.run(host="0.0.0.0", port=5000)
